TEXTHTML = '/**\n * Guide text → HTML: \'1. …\' lines become numbered steps, \'- …\' lines bullets, \'[ ] …\' / \'[x] …\' checklist items,\n * \'## …\' small headings, blank lines spacing. House\'s Future improvements use it too.\n */\nexport function textHtml(text) {\n    return text.split(\'\\n\').map(line => {\n        const t = line.trim();\n        if (!t) return \'<div class="g-gap"></div>\';\n        const head = /^#{1,3}\\s+(.*)$/.exec(t);\n        if (head) return `<h4 class="g-head">${esc(head[1])}</h4>`;\n        const check = /^\\[([ xX])\\]\\s*(.*)$/.exec(t);\n        if (check) return `<div class="g-step${check[1] === \' \' ? \'\' : \' g-done\'}"><span class="g-num">${check[1] === \' \' ? \'☐\' : \'☑\'}</span><span>${esc(check[2])}</span></div>`;\n        const step = /^(\\d+[.)])\\s+(.*)$/.exec(t);\n        if (step) return `<div class="g-step"><span class="g-num">${esc(step[1])}</span><span>${esc(step[2])}</span></div>`;\n        const bullet = /^[-•*]\\s+(.*)$/.exec(t);\n        if (bullet) return `<div class="g-step"><span class="g-num">•</span><span>${esc(bullet[1])}</span></div>`;\n        return `<p>${esc(t)}</p>`;\n    }).join(\'\');\n}\n'
APPT = "/**\n * The banner at the top of a pet's page: the next appointment on or after `today` (rows with a YYYY-MM-DD Date).\n * { level: 'none' } (red) when there isn't one, 'soon' (yellow) when it's within 14 days, else 'later' (green);\n * with next (the row) and days (0 = today).\n */\nexport function appointmentStatus(rows, today = new Date()) {\n    const SOON_DAYS = 14;\n    const pad = n => String(n).padStart(2, '0');\n    const todayIso = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;\n    const next = rows.filter(r => /^\\d{4}-\\d{2}-\\d{2}$/.test(r.Date || '') && r.Date >= todayIso)\n        .sort((a, b) => a.Date.localeCompare(b.Date) || String(a.Time || '').localeCompare(String(b.Time || '')))[0];\n    if (!next) return { level: 'none' };\n    const [y, m, d] = next.Date.split('-').map(Number);\n    const days = Math.round((new Date(y, m - 1, d) - new Date(today.getFullYear(), today.getMonth(), today.getDate())) / 86400000);\n    return { level: days <= SOON_DAYS ? 'soon' : 'later', next, days };\n}\n"
